package cl.teamdex.app;

import android.app.Activity;
import android.app.AlertDialog;
import android.content.Context;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.os.Bundle;
import android.text.InputType;
import android.view.Gravity;
import android.view.View;
import android.view.ViewGroup;
import android.widget.*;
import cl.teamdex.app.data.PokeApiClient;
import cl.teamdex.app.data.TeamDexDatabase;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;

public class MainActivity extends Activity {
    private final int red=Color.rgb(194,36,50), ink=Color.rgb(48,36,38), soft=Color.rgb(250,243,241), muted=Color.rgb(123,110,110);
    private TeamDexDatabase db;
    private FrameLayout host;
    private String level="novato";
    private static final String[] REGIONS={"Kanto","Johto","Hoenn","Sinnoh","Unova","Kalos","Alola","Galar","Paldea"};
    private static final int[] STARTS={1,152,252,387,494,650,722,810,899};
    private static final int[] COUNTS={151,100,135,107,156,72,88,89,120};

    @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(Color.rgb(151,24,37));getWindow().setNavigationBarColor(Color.rgb(55,20,24));db=TeamDexDatabase.get(this);level=db.getLevel();host=new FrameLayout(this);setContentView(host);if(!isConfigured())showLevel(true);else home();}
    private boolean isConfigured(){return getPreferences(MODE_PRIVATE).getBoolean("configured",false);}
    private int dp(float v){return (int)(v*getResources().getDisplayMetrics().density+.5f);}
    private GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
    private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
    private LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
    private TextView text(String s,int size,int color,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(color);if(bold)v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return v;}
    private TextView button(String s,Runnable action){TextView v=text(s,16,Color.WHITE,true);v.setGravity(Gravity.CENTER);v.setPadding(dp(18),dp(14),dp(18),dp(14));v.setBackground(shape(red,16));v.setOnClickListener(w->action.run());return v;}
    private TextView pill(String s,Runnable action){TextView v=text(s,14,ink,true);v.setGravity(Gravity.CENTER);v.setPadding(dp(15),dp(12),dp(15),dp(12));v.setBackground(shape(Color.WHITE,14));v.setOnClickListener(w->action.run());return v;}
    private LinearLayout.LayoutParams lp(int w,int h){return new LinearLayout.LayoutParams(w<0?w:dp(w),h<0?h:dp(h));}
    private void base(String title,String subtitle,boolean back){LinearLayout page=column();page.setBackgroundColor(soft);LinearLayout head=column();head.setPadding(dp(20),dp(18),dp(20),dp(15));head.setBackground(shape(Color.WHITE,0));if(back){TextView b=text("‹  Volver",15,red,true);b.setOnClickListener(v->backAction.run());head.addView(b,lp(-2,-2));}head.addView(text(title,27,ink,true),lp(-1,-2));if(subtitle!=null){TextView sub=text(subtitle,14,muted,false);LinearLayout.LayoutParams p=lp(-1,-2);p.topMargin=dp(5);head.addView(sub,p);}page.addView(head);ScrollView scroll=new ScrollView(this);LinearLayout body=column();body.setPadding(dp(18),dp(18),dp(18),dp(25));scroll.addView(body);page.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));host.removeAllViews();host.addView(page);content=body;}
    private LinearLayout content;
    private Runnable backAction = () -> home();
    private void gap(int h){content.addView(new View(this),lp(1,h));}
    private TextView section(String s){TextView t=text(s,20,ink,true);content.addView(t,lp(-1,-2));gap(9);return t;}
    private void tile(String icon,String title,String desc,Runnable click){LinearLayout card=row();card.setPadding(dp(15),dp(16),dp(15),dp(16));card.setBackground(shape(Color.WHITE,18));TextView mark=text(icon,27,red,true);mark.setGravity(Gravity.CENTER);card.addView(mark,lp(48,48));LinearLayout details=column();details.setPadding(dp(12),0,dp(8),0);details.addView(text(title,17,ink,true));TextView d=text(desc,13,muted,false);d.setPadding(0,dp(4),0,0);details.addView(d);card.addView(details,new LinearLayout.LayoutParams(0,-2,1));card.addView(text("›",28,red,true));card.setOnClickListener(v->click.run());content.addView(card,lp(-1,-2));gap(11);}
    private void showLevel(boolean first){base(first?"¡Bienvenido a TeamDex!":"Configuración","Elige cómo quieres ver la información Pokémon.",!first);section("¿Cuál es tu nivel?");gap(8);tile("✦","Novato","Explicaciones sencillas y amigables.",()->saveLevel("novato",first));tile("★","Experto","Información más técnica y detallada.",()->saveLevel("experto",first));gap(8);content.addView(button(first?"Comenzar":"Guardar preferencia",()->{if(!first)saveLevel(level,false);else Toast.makeText(this,"Selecciona Novato o Experto para continuar.",Toast.LENGTH_SHORT).show();}),lp(-1,-2));}
    private void saveLevel(String value,boolean first){level=value;db.saveLevel(value);getPreferences(MODE_PRIVATE).edit().putBoolean("configured",true).apply();if(first)home();else{Toast.makeText(this,"Preferencia guardada.",Toast.LENGTH_SHORT).show();}}
    private void home(){backAction=()->home();base("TeamDex","Crea y organiza tus equipos Pokémon.",false);gap(12);LinearLayout hero=column();hero.setGravity(Gravity.CENTER);hero.setPadding(dp(15),dp(22),dp(15),dp(28));hero.setBackground(shape(Color.WHITE,22));TextView ball=text("◉",72,red,true);ball.setGravity(Gravity.CENTER);hero.addView(ball);hero.addView(text("Mi Pokédex",29,ink,true));TextView copy=text("Explora regiones, guarda favoritos y crea equipos a tu manera.",15,muted,false);copy.setGravity(Gravity.CENTER);copy.setPadding(dp(15),dp(8),dp(15),0);hero.addView(copy);content.addView(hero,lp(-1,-2));gap(18);tile("◉","Pokémon","Explora nueve regiones y consulta la Pokédex.",()->regions());tile("◎","Mis equipos","Organiza equipos de hasta seis Pokémon.",()->teams());tile("⚙","Configuración","Nivel actual: "+(level.equals("novato")?"Novato":"Experto"),()->showLevel(false));}
    private void regions(){backAction=()->home();base("Pokémon","Selecciona una región para explorar.",true);section("Regiones");for(int i=0;i<REGIONS.length;i++){final int j=i;tile("⌖",REGIONS[i],COUNTS[i]+" Pokémon · #"+STARTS[i]+"–"+(STARTS[i]+COUNTS[i]-1),()->loadRegion(j));}tile("♥","Pokémon favoritos","Tu lista guardada en este dispositivo.",()->favorites());}
    private void loadRegion(int index){backAction=()->regions();base(REGIONS[index],"Catálogo Pokémon · busca por nombre o número.",true);loadPokemonPage(STARTS[index],COUNTS[index],false,0);}
    private void loadPokemonPage(int start,int count,boolean all,long teamId){LinearLayout searchRow=row();EditText search=new EditText(this);search.setSingleLine(true);search.setHint("Buscar Pokémon o número...");search.setInputType(InputType.TYPE_CLASS_TEXT);search.setPadding(dp(14),0,dp(14),0);search.setBackground(shape(Color.WHITE,16));searchRow.addView(search,new LinearLayout.LayoutParams(0,dp(52),1));content.addView(searchRow,lp(-1,52));gap(12);TextView status=text("Cargando Pokédex...",14,muted,false);content.addView(status);LinearLayout list=column();content.addView(list);PokeApiClient.Callback<List<TeamDexDatabase.Pokemon>> callback=(data,error)->{if(isFinishing())return;status.setVisibility(View.GONE);if(error!=null){TextView retry=text("No se pudieron cargar los Pokémon. Revisa Internet y vuelve a abrir la región.",15,muted,false);list.addView(retry);return;}renderPokemonList(list,data,search,teamId);};if(all)PokeApiClient.listAll(callback);else PokeApiClient.listRegion(start,count,callback);}
    private void renderPokemonList(LinearLayout target,List<TeamDexDatabase.Pokemon> data,EditText search,long teamId){Runnable filter=()->{String q=search.getText().toString().trim().toLowerCase(Locale.ROOT);target.removeAllViews();int shown=0;for(TeamDexDatabase.Pokemon p:data){boolean match=q.isEmpty()||p.name.toLowerCase(Locale.ROOT).contains(q)||String.valueOf(p.id).equals(q);if(!match)continue;shown++;LinearLayout item=row();item.setPadding(dp(12),dp(10),dp(12),dp(10));item.setBackground(shape(Color.WHITE,16));TextView ball=text("◉",28,red,true);item.addView(ball,lp(40,42));LinearLayout info=column();info.setPadding(dp(10),0,dp(5),0);info.addView(text("#"+String.format(Locale.US,"%03d",p.id)+"  "+p.name,16,ink,true));TextView types=text("Toca para ver detalles",12,muted,false);info.addView(types);item.addView(info,new LinearLayout.LayoutParams(0,-2,1));if(teamId==0)item.addView(text(db.isFavorite(p.id)?"♥":"♡",22,red,true));item.setOnClickListener(v->{if(teamId>0)addToTeam(teamId,p);else detail(p);});target.addView(item,lp(-1,-2));LinearLayout.LayoutParams m=lp(-1,-2);m.bottomMargin=dp(8);item.setLayoutParams(m);}if(shown==0)target.addView(text("No se encontraron Pokémon.",14,muted,false));};search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){filter.run();}public void afterTextChanged(android.text.Editable e){}});filter.run();}
    private void favorites(){backAction=()->regions();base("Pokes favoritos","Tus favoritos se consultan y editan en SQLite.",true);List<TeamDexDatabase.Pokemon> fav=db.getFavorites();if(fav.isEmpty()){content.addView(text("Todavía no tienes favoritos. Explora una región y abre la ficha de un Pokémon para guardarlo.",16,muted,false));return;}for(TeamDexDatabase.Pokemon p:fav){tile("♥",p.name,"#"+p.id+" · Abrir ficha",()->detail(p));TextView edit=pill("Editar etiqueta · "+p.name,()->editFavorite(p));LinearLayout.LayoutParams prm=lp(-1,-2);prm.bottomMargin=dp(8);content.addView(edit,prm);TextView remove=pill("Eliminar favorito · "+p.name,()->new AlertDialog.Builder(this).setMessage("¿Quitar "+p.name+" de favoritos?").setNegativeButton("Cancelar",null).setPositiveButton("Quitar",(d,w)->{db.deleteFavorite(p.id);favorites();}).show());prm=lp(-1,-2);prm.bottomMargin=dp(15);content.addView(remove,prm);}}
    private void editFavorite(TeamDexDatabase.Pokemon p){EditText input=new EditText(this);input.setSingleLine(true);input.setText(p.name);new AlertDialog.Builder(this).setTitle("Editar etiqueta del favorito").setView(input).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",(d,w)->{try{db.updateFavoriteName(p.id,input.getText().toString());favorites();}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}}).show();}
    private void detail(TeamDexDatabase.Pokemon pokemon){backAction=()->regions();base(pokemon.name,"Pokédex #"+pokemon.id,false);TextView loading=text("Consultando ficha Pokémon...",15,muted,false);content.addView(loading);PokeApiClient.detail(pokemon.id,(data,error)->{if(isFinishing())return;content.removeAllViews();if(error!=null){content.addView(text("No fue posible cargar la ficha. Revisa la conexión.",16,muted,false));return;}TextView art=text("◉",84,red,true);art.setGravity(Gravity.CENTER);content.addView(art,lp(-1,145));section("Información");infoTile("Tipo",data.types.isEmpty()?"Sin información":join(data.types));infoTile("Habilidades",data.abilities.isEmpty()?"Sin información":join(data.abilities));if(data.description!=null){TextView desc=text(data.description.replace('\n',' '),15,ink,false);content.addView(desc,lp(-1,-2));gap(14);}tile(db.isFavorite(pokemon.id)?"♥":"♡",db.isFavorite(pokemon.id)?"Quitar de favoritos":"Agregar a favoritos","Se guarda en SQLite.",()->{db.toggleFavorite(pokemon);detail(pokemon);});tile("＋","Agregar a un equipo","Elige uno de tus equipos guardados.",()->chooseTeam(pokemon));});}
    private String join(List<String> values){StringBuilder b=new StringBuilder();for(String s:values){if(b.length()>0)b.append(" · ");b.append(PokeApiClient.slugToName(s));}return b.toString();}
    private void teams(){backAction=()->home();base("Mis equipos","Tus equipos quedan guardados en SQLite.",true);TextView create=button("＋  Crear equipo",()->teamNameDialog(null));content.addView(create,lp(-1,-2));gap(18);List<TeamDexDatabase.Team> list=db.getTeams();if(list.isEmpty()){section("Aún no tienes equipos");content.addView(text("Crea tu primer equipo Pokémon para empezar.",15,muted,false));return;}for(TeamDexDatabase.Team team:list)tile("◎",team.name,team.size+" / 6 Pokémon",()->teamDetail(team));for(TeamDexDatabase.Team team:list){TextView edit=pill("Editar nombre · "+team.name,()->teamNameDialog(team));LinearLayout.LayoutParams p=lp(-1,-2);p.bottomMargin=dp(8);content.addView(edit,p);TextView del=pill("Eliminar · "+team.name,()->confirmDelete(team));p=lp(-1,-2);p.bottomMargin=dp(15);content.addView(del,p);}}
    private void teamNameDialog(TeamDexDatabase.Team team){EditText input=new EditText(this);input.setSingleLine(true);input.setHint("Ej.: Equipo aventura");if(team!=null)input.setText(team.name);new AlertDialog.Builder(this).setTitle(team==null?"Crear equipo":"Cambiar nombre").setView(input).setNegativeButton("Cancelar",null).setPositiveButton(team==null?"Crear":"Guardar",(d,w)->{try{if(team==null)db.createTeam(input.getText().toString());else db.updateTeam(team.id,input.getText().toString());teams();}catch(Exception e){Toast.makeText(this,e.getMessage()!=null&&e.getMessage().contains("UNIQUE")?"Ya existe un equipo con ese nombre.":e.getMessage(),Toast.LENGTH_LONG).show();}}).show();}
    private void confirmDelete(TeamDexDatabase.Team team){new AlertDialog.Builder(this).setTitle("Eliminar equipo").setMessage("¿Eliminar "+team.name+" y sus Pokémon?").setNegativeButton("Cancelar",null).setPositiveButton("Eliminar",(d,w)->{db.deleteTeam(team.id);teams();}).show();}
    private void teamDetail(TeamDexDatabase.Team team){backAction=()->teams();base(team.name,"Integrantes · máximo 6 Pokémon",true);TextView add=button("＋  Añadir Pokémon",()->{if(db.countTeamPokemon(team.id)>=6){Toast.makeText(this,"Tu equipo ya tiene seis Pokémon.",Toast.LENGTH_SHORT).show();return;}backAction=()->teamDetail(team);base("Añadir Pokémon","Busca cualquier especie disponible.",true);loadPokemonPage(1,1018,true,team.id);});content.addView(add,lp(-1,-2));gap(15);List<TeamDexDatabase.Pokemon> members=db.getTeamPokemon(team.id);section(members.size()+" / 6 Pokémon");if(members.isEmpty())content.addView(text("Agrega Pokémon para comenzar a formar tu equipo.",15,muted,false));for(TeamDexDatabase.Pokemon p:members){tile(p.shiny?"✦":"◉",p.name,"#"+p.id+(p.shiny?" · Shiny":""),()->editPokemon(team,p));TextView remove=pill("Quitar del equipo",()->new AlertDialog.Builder(this).setMessage("¿Quitar a "+p.name+" de este equipo?").setNegativeButton("Cancelar",null).setPositiveButton("Quitar",(d,w)->teamDetailAfterRemove(team,p)).show());content.addView(remove,lp(-1,-2));gap(12);}}
    private void teamDetailAfterRemove(TeamDexDatabase.Team team,TeamDexDatabase.Pokemon p){db.removePokemon(team.id,p.id);teamDetail(team);}
    private void addToTeam(long teamId,TeamDexDatabase.Pokemon p){try{db.addPokemon(teamId,p);Toast.makeText(this,p.name+" agregado al equipo.",Toast.LENGTH_SHORT).show();teamDetailById(teamId);}catch(Exception e){Toast.makeText(this,e.getMessage()!=null&&e.getMessage().contains("UNIQUE")?"Ese Pokémon ya está en el equipo.":e.getMessage(),Toast.LENGTH_LONG).show();}}
    private void teamDetailById(long id){for(TeamDexDatabase.Team team:db.getTeams())if(team.id==id){teamDetail(team);return;}teams();}
    private void chooseTeam(TeamDexDatabase.Pokemon p){List<TeamDexDatabase.Team> teams=db.getTeams();if(teams.isEmpty()){new AlertDialog.Builder(this).setMessage("Primero crea un equipo.").setPositiveButton("Crear",(d,w)->teamNameDialog(null)).setNegativeButton("Cancelar",null).show();return;}String[] names=new String[teams.size()];for(int i=0;i<teams.size();i++)names[i]=teams.get(i).name+" ("+teams.get(i).size+"/6)";new AlertDialog.Builder(this).setTitle("Agregar a equipo").setItems(names,(d,w)->{try{db.addPokemon(teams.get(w).id,p);Toast.makeText(this,"Agregado a "+teams.get(w).name,Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}}).show();}
    private void editPokemon(TeamDexDatabase.Team team,TeamDexDatabase.Pokemon p){backAction=()->teamDetail(team);base(p.name,"Configura el set de combate.",true);TextView loading=text("Cargando opciones Pokémon...",14,muted,false);content.addView(loading);PokeApiClient.detail(p.id,(data,error)->{if(isFinishing())return;content.removeAllViews();if(error!=null){content.addView(text("No se pudieron obtener los detalles de la API.",15,muted,false));return;}Spinner ability=spinner(data.abilities,p.ability);Spinner item=spinner(data.items,p.item);content.addView(text("Habilidad",15,ink,true));content.addView(ability,lp(-1,52));gap(10);content.addView(text("Objeto equipado",15,ink,true));content.addView(item,lp(-1,52));gap(10);Spinner[] moves=new Spinner[4];for(int i=0;i<4;i++){content.addView(text("Movimiento "+(i+1),15,ink,true));moves[i]=spinner(data.moves,p.moves[i]);content.addView(moves[i],lp(-1,52));gap(7);}CheckBox shiny=new CheckBox(this);shiny.setText("Pokémon shiny");shiny.setTextColor(ink);shiny.setChecked(p.shiny);content.addView(shiny);gap(12);content.addView(button("Guardar cambios",()->{String[] selected=new String[4];for(int i=0;i<4;i++)selected[i]=(String)moves[i].getSelectedItem();db.updatePokemon(team.id,p.id,(String)ability.getSelectedItem(),(String)item.getSelectedItem(),selected,shiny.isChecked());teamDetail(team);}),lp(-1,-2));});}
    private Spinner spinner(List<String> values,String selected){List<String> options=new ArrayList<>();options.add("— Sin selección —");for(String s:values)options.add(PokeApiClient.slugToName(s));Spinner spinner=new Spinner(this);ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,options);spinner.setAdapter(adapter);if(selected!=null){String wanted=PokeApiClient.slugToName(selected);for(int i=0;i<options.size();i++)if(options.get(i).equalsIgnoreCase(wanted))spinner.setSelection(i);}return spinner;}
    @Override public void onBackPressed(){backAction.run();}
    private void infoTile(String title,String value){LinearLayout card=column();card.setPadding(dp(13),dp(14),dp(13),dp(14));card.setBackground(shape(Color.WHITE,15));card.addView(text(title,14,muted,false));card.addView(text(value,16,ink,true));LinearLayout.LayoutParams p=lp(-1,-2);p.bottomMargin=dp(8);content.addView(card,p);}
}







